{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.12.13","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"none","dataSources":[],"dockerImageVersionId":28755,"isInternetEnabled":false,"language":"python","sourceType":"notebook","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [code]\n!pip install torchio pandas nibabel --quiet\n\n# %% [code]\nfrom __future__ import annotations\nfrom pathlib import Path\nfrom collections import Counter\nimport re\nimport pandas as pd\nimport torch\nimport torchio as tio\nfrom torch.utils.data import Dataset, DataLoader, WeightedRandomSampler\n\n# %% [code]\nDATA_ROOT   = \"/kaggle/input/datasets/sparkedwakanda26/skull-stripped-mri/skull_stripped_data\"\nTSV_PATH    = \"/kaggle/input/datasets/em07adoz/participants-info/participant-info.tsv\"\n\nMODALITY    = \"T1w\"      \nSLICE_MODE  = \"axial\"    \nAXIAL_RANGE = (0.0, 1.0)  \nBATCH_SIZE  = 8\nN_FOLDS     = 5\nTEST_FRAC   = 0.12\nRANDOM_SEED = 42\nLABEL_MAP   = {\"Control\": 0, \"Dementia\": 1, \"Parkinson\": 2}\n\ntorch.manual_seed(RANDOM_SEED)\n\n# %% [code]\n#Load labels\ndemo = pd.read_csv(TSV_PATH, sep=\"\\t\")\ndemo.columns = demo.columns.str.strip() \n\n# dataset has a known typo (\"ClincalGroup\"); handle both spellings\nlabel_col = next(\n    (c for c in [\"ClincalGroup\", \"ClinicalGroup\"] if c in demo.columns), None\n)\nif label_col is None:\n    raise KeyError(f\"Clinical group column not found. Got: {list(demo.columns)}\")\n\nlabel_lookup = {\n    int(row[\"Subject\"]): LABEL_MAP[row[label_col].strip()]\n    for _, row in demo.iterrows()\n}\n\nprint(f\"Labels loaded: {len(label_lookup)} subjects\")\nprint(demo[label_col].value_counts().to_string())\n\n# %% [code]\nimport json\nfrom tqdm.notebook import tqdm\n\nCACHE_PATH = \"/kaggle/working/shapes_cache.json\"\nMIN_SLICES = 8  # exclude subjects with fewer than this many slices\n\ndef find_modality_file(subj_dir: Path, modality: str) -> Path | None:\n    for mod_dir in sorted(subj_dir.iterdir()):\n        if not mod_dir.is_dir():\n            continue\n        clean_name = re.sub(r\"\\.id-[^.]+$\", \"\", mod_dir.name).lower()\n        if modality.lower() in clean_name:\n            nii_files = sorted(mod_dir.glob(\"*.nii\"))\n            if nii_files:\n                return nii_files[0]\n    return None\n\n\nif Path(CACHE_PATH).exists():\n    with open(CACHE_PATH) as f:\n        cache = json.load(f)\n    records = cache[\"records\"]\n    shapes  = [tuple(s) for s in cache[\"shapes\"]]\n    skipped = cache.get(\"skipped\", [])\n    print(\"Loaded from cache.\")\nelse:\n    root    = Path(DATA_ROOT)\n    records = []\n    shapes  = []\n    skipped = []\n\n    for subj_dir in tqdm(sorted(root.glob(\"sub-*\")), desc=\"Scanning subjects\"):\n        subj_num = int(subj_dir.name.split(\"-\")[1])\n        label    = label_lookup.get(subj_num)\n\n        if label is None:\n            skipped.append(f\"{subj_dir.name}: not in TSV\")\n            continue\n\n        nii_path = find_modality_file(subj_dir, MODALITY)\n        if nii_path is None:\n            skipped.append(f\"{subj_dir.name}: no {MODALITY} file\")\n            continue\n\n        img = tio.ScalarImage(str(nii_path))\n        _, W, H, D = img.shape\n\n        # skip subjects with too few slices - these are broken files\n        if D < MIN_SLICES:\n            skipped.append(f\"{subj_dir.name}: only {D} slices (min is {MIN_SLICES})\")\n            continue\n\n        shapes.append((W, H, D))\n        records.append({\n            \"path\":       str(nii_path),\n            \"label\":      label,\n            \"subject_id\": subj_dir.name,\n            \"n_slices\":   D,   # actual number of slices for this subject\n        })\n\n    with open(CACHE_PATH, \"w\") as f:\n        json.dump({\"records\": records, \"shapes\": shapes, \"skipped\": skipped}, f)\n    print(\"Scan complete. Cached for next run.\")\n\n\nTARGET_SIZE = (max(s[0] for s in shapes),\n               max(s[1] for s in shapes),\n               max(s[2] for s in shapes))\n\nprint(f\"Modality       : {MODALITY}\")\nprint(f\"Subjects found : {len(records)}  |  Skipped: {len(skipped)}\")\nprint(f\"Max dims (W x H x D): {TARGET_SIZE}\")\nif skipped:\n    for s in skipped:\n        print(f\"  SKIP: {s}\")\n\n# %% [code]\n#dataset classes\n_VOLUME_TRANSFORM = tio.Compose([\n    tio.ToCanonical(),\n    tio.RescaleIntensity(out_min_max=(0, 1)),\n    tio.CropOrPad(TARGET_SIZE),\n])\n\n\nclass BrainMRI3DDataset(Dataset):\n    \"\"\"Full 3D volume per subject. Output shape: (1, W, H, D).\"\"\"\n\n    def __init__(self, records, transform=_VOLUME_TRANSFORM):\n        self.records   = records\n        self.transform = transform\n\n    def __len__(self):\n        return len(self.records)\n\n    def __getitem__(self, idx):\n        rec  = self.records[idx]\n        subj = tio.Subject(img=tio.ScalarImage(rec[\"path\"]))\n        if self.transform:\n            subj = self.transform(subj)\n        return {\n            \"image\":      subj.img.data,\n            \"label\":      torch.tensor(rec[\"label\"]),\n            \"subject_id\": rec[\"subject_id\"],\n        }\n\n\nclass BrainMRIAxialDataset(Dataset):\n    \"\"\"\n    Axial slices for 2D foundation models. Output shape: (1, H, W).\n    Uses each subject's actual slice count so no zero-padded slices are returned.\n    \"\"\"\n\n    def __init__(self, records, target_size, axial_range=(0.0, 1.0), transform=None):\n        self._vol_transform = _VOLUME_TRANSFORM\n        self.transform      = transform\n\n        self.items = []\n        for rec in records:\n            D  = rec[\"n_slices\"]\n            lo = int(D * axial_range[0])\n            hi = int(D * axial_range[1])\n            hi = max(hi, lo + 1)\n            for s in range(lo, hi):\n                self.items.append({\n                    \"path\":       rec[\"path\"],\n                    \"label\":      rec[\"label\"],\n                    \"subject_id\": rec[\"subject_id\"],\n                    \"slice_idx\":  s,\n                })\n\n        print(f\"  AxialDataset: {len(records)} subjects -> {len(self.items)} total slices\")\n\n    def __len__(self):\n        return len(self.items)\n\n    def __getitem__(self, idx):\n        item = self.items[idx]\n        subj = tio.Subject(img=tio.ScalarImage(item[\"path\"]))\n        subj = self._vol_transform(subj)\n\n        s        = item[\"slice_idx\"]\n        slice_2d = subj.img.data[0, :, :, s].T.unsqueeze(0)\n\n        if self.transform:\n            slice_2d = self.transform(slice_2d)\n\n        return {\n            \"image\":      slice_2d,\n            \"label\":      torch.tensor(item[\"label\"]),\n            \"subject_id\": item[\"subject_id\"],\n            \"slice_idx\":  s,\n        }\n\n\nprint(\"Dataset classes ready.\")\n\n# %% [code]\n#Stratified train/test split\n\n# split per class so each class appears in both splits at the right ratio\nall_labels = torch.tensor([r[\"label\"] for r in records])\nclasses    = torch.unique(all_labels)\nrng        = torch.Generator().manual_seed(RANDOM_SEED)\n\ntrain_idx, test_idx = [], []\nfor c in classes:\n    idx    = torch.where(all_labels == c)[0]\n    idx    = idx[torch.randperm(len(idx), generator=rng)]\n    n_test = max(1, round(len(idx) * TEST_FRAC))\n    test_idx.extend(idx[:n_test].tolist())\n    train_idx.extend(idx[n_test:].tolist())\n\ntrain_records = [records[i] for i in train_idx]\ntest_records  = [records[i] for i in test_idx]\n\nprint(f\"Train: {len(train_records)}  |  Test: {len(test_records)}\")\ninv_label = {v: k for k, v in LABEL_MAP.items()}\nfor name, recs in [(\"Train\", train_records), (\"Test\", test_records)]:\n    counts = Counter(inv_label[r[\"label\"]] for r in recs)\n    print(f\"  {name}: {dict(counts)}\")\n\n# %% [code]\n#DataLoader\n\ndef make_weighted_sampler(recs: list[dict]) -> WeightedRandomSampler:\n    \"\"\"Oversample minority classes so each class is seen equally during training.\"\"\"\n    labs    = torch.tensor([r[\"label\"] for r in recs])\n    counts  = torch.bincount(labs, minlength=len(LABEL_MAP)).float()\n    weights = 1.0 / counts\n    return WeightedRandomSampler(weights[labs], len(recs), replacement=True)\n\n\ndef make_loader(\n    recs: list[dict],\n    slice_mode: str = SLICE_MODE,\n    batch_size: int = BATCH_SIZE,\n    shuffle: bool   = True,\n    sampler         = None,\n    extra_transform = None,  \n) -> DataLoader:\n\n    if slice_mode == \"axial\":\n        ds = BrainMRIAxialDataset(recs, TARGET_SIZE, AXIAL_RANGE, transform=extra_transform)\n    elif slice_mode == \"3d\":\n        ds = BrainMRI3DDataset(recs)\n    else:\n        raise ValueError(f\"slice_mode must be 'axial' or '3d', got '{slice_mode}'\")\n\n    return DataLoader(\n        ds,\n        batch_size  = batch_size,\n        shuffle     = (shuffle and sampler is None),  # shuffle is ignored when sampler is set\n        sampler     = sampler,\n        num_workers = 0,\n        pin_memory  = False,\n    )\n\n\nprint(\"DataLoader factory ready.\")\n\n# %% [code]\n#5-fold cross-validation\n\nperm      = torch.randperm(len(train_records), generator=rng)\nfold_size = len(perm) // N_FOLDS\nfold_loaders = []\n\nfor fold in range(N_FOLDS):\n    val_start = fold * fold_size\n    val_end   = val_start + fold_size if fold < N_FOLDS - 1 else len(perm)\n\n    val_idx  = perm[val_start:val_end].tolist()\n    tr_idx   = torch.cat([perm[:val_start], perm[val_end:]]).tolist()\n\n    fold_train = [train_records[i] for i in tr_idx]\n    fold_val   = [train_records[i] for i in val_idx]\n\n    sampler      = make_weighted_sampler(fold_train)\n    train_loader = make_loader(fold_train, shuffle=True, sampler=sampler)\n    val_loader   = make_loader(fold_val,   shuffle=False)\n    fold_loaders.append((train_loader, val_loader))\n\n    print(f\"Fold {fold+1}: train={len(fold_train)} subjects ({len(train_loader)} batches) | \"\n          f\"val={len(fold_val)} subjects ({len(val_loader)} batches)\")\n\ntest_loader = make_loader(test_records, shuffle=False)\nprint(f\"\\nTest : {len(test_records)} subjects | {len(test_loader)} batches\")\nprint(f\"Mode : {SLICE_MODE} | Modality: {MODALITY} | Target size: {TARGET_SIZE}\")\n\n# %% [code]\n# Test Run\n\ntrain_loader_fold1, _ = fold_loaders[0]\nbatch = next(iter(train_loader_fold1))\n\nprint(\"Image shape :\", batch[\"image\"].shape)   # axial: (8, 1, H, W) | 3d: (8, 1, W, H, D)\nprint(\"Labels      :\", batch[\"label\"].tolist())\nprint(\"Value range :\", f\"[{batch['image'].min():.3f}, {batch['image'].max():.3f}]\")\nif SLICE_MODE == \"axial\":\n    print(\"Slice idx   :\", batch[\"slice_idx\"].tolist())\n\n# %% [code]\n","metadata":{"_uuid":"f5c47927-552d-40bb-9d1e-9d00d6c64ee4","_cell_guid":"f13d32a2-7851-4272-815e-b2344d9d5d28","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}